"use client";
import { useState, useEffect } from "react";
import { useRouter } from 'next/router';
import axios from "axios";
import { TextField, Button, MenuItem, Select, FormControl, InputLabel } from "@mui/material";
import { useSnackbar } from 'notistack';

export default function EditGroupe() {
  const router = useRouter();
  const { idGroupe } = router.query; // ID du groupe depuis l'URL
  const [groupe, setGroupe] = useState(null);
  const [tuteurs, setTuteurs] = useState([]);
  const [sujets, setSujets] = useState([]);
  const [loading, setLoading] = useState(true);
  const { enqueueSnackbar } = useSnackbar();

  useEffect(() => {
    if (idGroupe) {
      fetchGroupeData();
      fetchTuteursSujets();
    }
  }, [idGroupe]);

  const fetchGroupeData = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`http://localhost:5000/api/groupe/${idGroupe}`);
      setGroupe(response.data);
    } catch (error) {
      console.error("Erreur lors du chargement du groupe :", error);
      enqueueSnackbar('Erreur lors du chargement du groupe', { variant: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const fetchTuteursSujets = async () => {
    try {
      const [tuteursResponse, sujetsResponse] = await Promise.all([
        axios.get("http://localhost:5000/api/tuteurs"),
        axios.get("http://localhost:5000/api/sujets"),
      ]);
      setTuteurs(tuteursResponse.data);
      setSujets(sujetsResponse.data);
    } catch (error) {
      console.error("Erreur lors du chargement des tuteurs et sujets :", error);
      enqueueSnackbar('Erreur lors du chargement des tuteurs et sujets', { variant: 'error' });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!groupe.tuteur || !groupe.sujet) {
      enqueueSnackbar('Veuillez sélectionner un tuteur et un sujet.', { variant: 'warning' });
      return;
    }

    try {
      const response = await axios.put(`http://localhost:5000/api/groupe/${idGroupe}`, {
        tuteurId: groupe.tuteur.idTuteur,
        sujetId: groupe.sujet.idSujet,
      });
      enqueueSnackbar('Groupe mis à jour avec succès', { variant: 'success' });
      router.push('/gestion-groupes'); // Retour à la page de gestion des groupes
    } catch (error) {
      console.error("Erreur lors de la mise à jour du groupe :", error);
      enqueueSnackbar('Erreur lors de la mise à jour du groupe', { variant: 'error' });
    }
  };

  if (loading || !groupe) {
    return <div>Chargement...</div>;
  }

  return (
    <div className="container mx-auto p-6">
      <h2 className="text-2xl font-bold mb-4 text-blue-600">Éditer le Groupe</h2>
      <form onSubmit={handleSubmit}>
        <TextField
          label="Nom du Groupe"
          variant="outlined"
          fullWidth
          value={groupe.nomGroupe || ''}
          onChange={(e) => setGroupe({ ...groupe, nomGroupe: e.target.value })}
          className="mb-4"
        />
        <FormControl fullWidth className="mb-4">
          <InputLabel>Tuteur</InputLabel>
          <Select
            value={groupe.tuteur ? groupe.tuteur.idTuteur : ""}
            onChange={(e) => setGroupe({ ...groupe, tuteur: tuteurs.find(t => t.idTuteur === e.target.value) })}
            label="Tuteur"
          >
            {tuteurs.map((tuteur) => (
              <MenuItem key={tuteur.idTuteur} value={tuteur.idTuteur}>
                {tuteur.nom} {tuteur.prenom}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
        <FormControl fullWidth className="mb-4">
          <InputLabel>Sujet</InputLabel>
          <Select
            value={groupe.sujet ? groupe.sujet.idSujet : ""}
            onChange={(e) => setGroupe({ ...groupe, sujet: sujets.find(s => s.idSujet === e.target.value) })}
            label="Sujet"
          >
            {sujets.map((sujet) => (
              <MenuItem key={sujet.idSujet} value={sujet.idSujet}>
                {sujet.titre}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
        <Button type="submit" variant="contained" color="primary" className="mt-4">
          Mettre à jour
        </Button>
      </form>
    </div>
  );
}
